+    let mut ino: ino_t = 0;
+    let rc = unsafe { systool_file_dev_ino(path.as_ptr(), &mut dev, &mut ino) };
+    if rc != 0 {
+        return Err(io::Error::last_os_error());
+    }
+    Ok((dev, ino))
+}

